CREATE OR REPLACE FUNCTION public.assert_coupon_usable(p_coupon coupons, p_tenant_id uuid, p_plan_id text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT p_coupon.is_active THEN
